    @PostMapping("/interfaces/{interfaceId}/operational-state") public Map<String,Object> interfaceOperationalState(@PathVariable String interfaceId,@RequestParam(required=false)String tenantId,@RequestBody Map<String,Object> body){return interfaceContracts.operationalState(tenant(tenantId),interfaceId,str(body,"healthStatus"),str(body,"conformanceStatus"),str(body,"circuitState"));}
    @GetMapping("/conformance/profiles") public List<Map<String,Object>> conformanceProfiles(@RequestParam(required=false)String tenantId){return conformance.profiles(tenant(tenantId));}
