    @PutMapping("/interfaces/{interfaceId}/credential-bindings/{bindingId}") public Map<String,Object> upsertCredentialBinding(@PathVariable String interfaceId,@PathVariable String bindingId,@RequestParam(required=false)String tenantId,@RequestBody Map<String,Object> body){return f0Security.upsertCredentialDraft(tenant(tenantId),interfaceId,bindingId,str(body,"securitySchemeRef"),str(body,"credentialType"),str(body,"secretRef"),str(body,"headerName"),str(body,"authScheme"));}
