    @PostMapping("/outbound-policies/{policyId}/activate") public Map<String,Object> activateOutboundPolicy(@PathVariable String policyId,@RequestParam(required=false)String tenantId){return f0Security.activateOutboundPolicy(tenant(tenantId),policyId);}
