    @PostMapping("/{peerId}/trust-evidence/{evidenceId}/revoke") public Map<String,Object> revokeTrustEvidence(@PathVariable String peerId,@PathVariable String evidenceId,@RequestParam(required=false)String tenantId,@RequestBody Map<String,Object> body){return trustEvidence.revoke(tenant(tenantId),peerId,evidenceId,str(body,"reason"));}
