    @GetMapping("/trust-assurance/policies/{policyId}") public Map<String,Object> assurancePolicy(@PathVariable String policyId,@RequestParam(required=false)String tenantId){return assurance.policy(tenant(tenantId),policyId);}
    @PutMapping("/trust-assurance/policies/{policyId}") public Map<String,Object> upsertAssurancePolicy(@PathVariable String policyId,@RequestParam(required=false)String tenantId,@RequestBody Map<String,Object> body){return assurance.upsertDraft(tenant(tenantId),policyId,str(body,"displayName"),str(body,"description"),listOfMaps(body,"rules"));}
    @PostMapping("/trust-assurance/policies/{policyId}/activate") public Map<String,Object> activateAssurancePolicy(@PathVariable String policyId,@RequestParam(required=false)String tenantId){return assurance.activate(tenant(tenantId),policyId);}
    @GetMapping("/{peerId}/trust-assurance") public Map<String,Object> trustAssurance(@PathVariable String peerId,@RequestParam(required=false)String interfaceId,@RequestParam(required=false)String tenantId){return assurance.explain(tenant(tenantId),peerId,interfaceId);}
    @GetMapping("/{peerId}/processing-attestations") public List<Map<String,Object>> processingAttestations(@PathVariable String peerId,@RequestParam(required=false)String tenantId,@RequestParam(defaultValue="false")boolean currentOnly){return processingAttestations.attestations(tenant(tenantId),peerId,currentOnly);}
