    @PostMapping("/{peerId}/processing-attestations/{attestationId}/verify") public Map<String,Object> verifyProcessingAttestation(@PathVariable String peerId,@PathVariable String attestationId,@RequestParam(required=false)String tenantId,@RequestBody(required=false)Map<String,Object> body){return processingAttestations.verify(tenant(tenantId),peerId,attestationId,body==null?null:str(body,"note"));}
    @PostMapping("/{peerId}/processing-attestations/{attestationId}/revoke") public Map<String,Object> revokeProcessingAttestation(@PathVariable String peerId,@PathVariable String attestationId,@RequestParam(required=false)String tenantId,@RequestBody Map<String,Object> body){return processingAttestations.revoke(tenant(tenantId),peerId,attestationId,str(body,"reason"));}
    @GetMapping("/version-policies") public List<Map<String,Object>> versionPolicies(@RequestParam(required=false)String tenantId){return versionPolicies.policies(tenant(tenantId));}
    @GetMapping("/version-policies/{policyId}") public Map<String,Object> versionPolicy(@PathVariable String policyId,@RequestParam(required=false)String tenantId){return versionPolicies.policy(tenant(tenantId),policyId);}
    @PutMapping("/version-policies/{policyId}") public Map<String,Object> upsertVersionPolicy(@PathVariable String policyId,@RequestParam(required=false)String tenantId,@RequestBody Map<String,Object> body){return versionPolicies.upsertDraft(tenant(tenantId),policyId,str(body,"displayName"),str(body,"description"),str(body,"preferredVersion"),str(body,"minAcceptedVersion"),str(body,"maxAcceptedVersion"),listOfStrings(body,"deprecatedVersions"),listOfMaps(body,"legacyAllowlist"));}
    @PostMapping("/version-policies/{policyId}/activate") public Map<String,Object> activateVersionPolicy(@PathVariable String policyId,@RequestParam(required=false)String tenantId){return versionPolicies.activate(tenant(tenantId),policyId);}
